@dataclass(slots=True, frozen=True)
class RouteRefInfo:
    """Decomposed route reference metadata."""

    raw: str
    prefix: str
    number: str
    route_type: RouteType
    canonical_name: str
    is_valid: bool
    qualifier: str | None = None

    @property
    def street_type(self) -> str:
        """Route type label (e.g. 'Quốc Lộ', 'Đường Tỉnh')."""
        if not self.is_valid:
            return ""
        name = self.canonical_name
        if self.qualifier and name.endswith(f" {self.qualifier}"):
            name = name[: -(len(self.qualifier) + 1)]
        if self.number and name.endswith(f" {self.number}"):
            name = name[: -(len(self.number) + 1)]
        return name or self.canonical_name


def _normalize_number(number: str) -> str:
    """Uppercase optional alphabetic suffixes while preserving digits and hyphens."""
    if not number:
        return number
    norm = _DASH_NORMALIZATION_RE.sub("-", number.strip())
    return norm.upper()


def _build_canonical_name(form: str, number: str, qualifier: str | None = None) -> str:
    label = _CANONICAL_LABELS[form]
    base = f"{label} {_normalize_number(number)}"
    if qualifier:
        return f"{base} {qualifier}"
    return base


def _split_compact_prefix(text: str) -> str:
    """Insert a space between compact route prefixes and following digits (e.g. QL1A -> QL 1A)."""
    split_dot = _COMPACT_PREFIX_RE.sub(r"\1 ", text)
    return _COMPACT_PREFIX_NO_DOT_RE.sub(r"\1 ", split_dot)


def _invalid_info(raw: str) -> RouteRefInfo:
    return RouteRefInfo(
        raw=raw,
        prefix="",
        number="",
        route_type="unknown",
        canonical_name="",
        is_valid=False,
        qualifier=None,
    )


def _is_bare_ct_prefix_match(match: re.Match[str], rule: _PrefixRule) -> bool:
    if rule.canonical_form != "cao_toc":
        return False
    return normalize_ascii(match.group("prefix")) == "ct"


def _is_standalone_route_ref(working_ascii: str, match: re.Match[str]) -> bool:
    before = working_ascii[: match.start()].strip()
    after = working_ascii[match.end() :].strip()
    before = _STANDALONE_ROUTE_PREFIX_STRIP_RE.sub("", before).strip()
    return not before and not after


def _is_ct_tower_block_number(number: str) -> bool:
    """CT1 / CT12A-style residential tower blocks, not zero-padded expressway codes."""
    norm = number.upper().strip()
    if not norm or norm.startswith("0"):
        return False
    m = _CT_TOWER_BLOCK_NUMBER_RE.fullmatch(norm)
    if not m:
        return False
    digits = int(m.group(1))
    letter = m.group(2)
    if letter is not None and digits <= 13:
        return True
    return digits <= 9 and letter is None


def _accept_bare_ct_expressway(working_ascii: str, match: re.Match[str], number_raw: str) -> bool:
    if _BUILDING_RESIDENTIAL_CTX_RE.search(working_ascii):
        return False
    if _EXPRESSWAY_INDICATOR_RE.search(working_ascii):
        return True
    if _is_standalone_route_ref(working_ascii, match):
        return not _is_ct_tower_block_number(number_raw)
    return False


def _resolve_suffix_qualifier(m_qual: re.Match[str]) -> str | None:
    raw = (m_qual.group("paren_q") or m_qual.group("bare_q") or "").strip().lower()
    raw = collapse_whitespace(raw)
    if not raw:
        return None
    if canon := _ROUTE_QUALIFIER_CANONICAL_MAP.get(raw):
        return canon
    if raw.startswith("nhanh "):
        parts = raw.split(maxsplit=1)
        return f"nhánh {parts[1].upper()}" if len(parts) > 1 else "nhánh"
    return None


